package com.diver.android

/**
 * Marks a Jetpack Navigation type-safe route as a Diver deeplink template and
 * (optionally) attaches a human-readable [name] and [description] that show up
 * in the `diver/app_urls.json` generated by the Diver KSP processor.
 *
 * Apply it to the `@Serializable` class or object you use as a navigation
 * destination:
 *
 * ```kotlin
 * @DiverRoute(name = "Settings", description = "App settings screen")
 * @Serializable
 * data class Settings(val tab: String? = null)
 * ```
 *
 * The route's host/path/query are derived from the class itself (see the
 * package README): the class name becomes the host, constructor parameters
 * without a default become path segments, and parameters with a default (or a
 * nullable type) become query parameters.
 *
 * This is the Android / Kotlin counterpart of the Dart `@DiverRoute`
 * annotation (`diver_flutter_annotation`) and the `defineDiverRoute` helper
 * (`diver-expo-builder/route`). Retention is [AnnotationRetention.SOURCE]: the
 * annotation is only read at build time by KSP and is never present in the
 * compiled app.
 */
@Retention(AnnotationRetention.SOURCE)
@Target(AnnotationTarget.CLASS)
annotation class DiverRoute(
    val name: String = "",
    val description: String = "",
)
